%[text] # Semi-automatic segmentation of a gastric tumour in venous-phase MRI
%[text] ```matlabCodeExample
%[text] 1. The method step by step on one development patient
%[text] 2. Seeds placed by clicking, as an operator would
%[text] 3. Effect of the threshold parameter k and of the opening radius
%[text] ```
addpath('src');
[P, Q] = methodConfig();
T = readCases('manifest/dev_cases.csv');
id = "0001498199";      % development patient with the median start-slice Dice (Fig. 2 of the report)
row = T(T.patient_id == id & T.modality == "V", :);
[I, S, sp] = readCase(row.img, row.seg);
pxmm = mean(sp(1:2));
fprintf('Patient %s: %d x %d x %d voxels of %.2f x %.2f x %.2f mm, tumour on %d slices\n', ... %[output:group:2d4dbc8b] %[output:4a88e388]
    id, size(I), sp, nnz(any(S, [1 2]))); %[output:group:2d4dbc8b] %[output:4a88e388]
%%
%[text] ## 1a. Seed placement
%[text] The operator scrolls to the slice where the tumour looks largest and clicks once on each visible piece of it. In the experiments both choices are simulated from the expert mask: the start slice k0 has the largest tumour area, and pickSeeds puts one seed near the centre of each piece of at least 10 mm^2.
[~, k0] = max(squeeze(sum(S, [1 2])));
seeds = pickSeeds(S(:, :, k0), sp(1:2), Q.minSeedAreaMM2);

f = figure('Name', '1a. Seed placement'); theme(f, 'light'); %[output:5c99c6cf]
imshow(mat2gray(I(:, :, k0)'), []); hold on; %[output:5c99c6cf]
visboundaries(S(:, :, k0)', 'Color', 'r', 'LineWidth', 0.8); %[output:5c99c6cf]
plot(seeds(:, 1), seeds(:, 2), 'y+', 'MarkerSize', 12, 'LineWidth', 2); %[output:5c99c6cf]
%title(sprintf('Start slice k_0 = %d (red: expert mask), %d seed(s)', k0, size(seeds, 1)));
%%
%[text] ## 1b. Start-slice segmentation, step by step
%[text] Inside a 60 mm ROI around the seeds the intensities are mapped to \[0, 1\] with the 1st and 99th percentiles and smoothed with a Gaussian filter (sigma 0.5 mm). The threshold keeps every pixel not darker than mu - k\*s, where mu and s are measured within 3 mm of the seeds (k = 1). Region growing keeps the part connected to the seeds (morphological reconstruction); a 3 mm opening cuts the thin bridges towards neighbouring structures, and the holes are filled.
[mask, box, steps] = segmentSlice(I(:, :, k0), seeds, sp(1:2), P);
rx = box(1):box(2);
ry = box(3):box(4);
s0 = seeds - [box(1) - 1, box(3) - 1];                    % seeds in ROI coordinates
% mu and s as in segmentSlice: pixels within seedRadiusMM of the seeds
nb = false(size(steps.roi));
nb(sub2ind(size(nb), s0(:, 1), s0(:, 2))) = true;
nb = imdilate(nb, strel('disk', max(round(P.seedRadiusMM / pxmm), 1), 0));
mu = mean(steps.roi(nb));
sd = max(std(steps.roi(nb)), 0.01);
t = mu - P.k * sd;

f = figure('Name', '1b. Start-slice segmentation', 'Position', [50 300 1600 380]); theme(f, 'light'); %[output:05ee0822]
tl = tiledlayout(f, 1, 5, 'TileSpacing', 'compact', 'Padding', 'compact');
nexttile(tl);
imshow(steps.roi', []); hold on; %[output:05ee0822]
visboundaries(nb', 'Color', 'c', 'LineWidth', 0.8); plot(s0(:, 1), s0(:, 2), 'y+', 'MarkerSize', 10, 'LineWidth', 1.5); %[output:05ee0822]
%title('normalised + Gaussian (cyan: 3 mm)');
nexttile(tl);  %[output:67752f08]
histogram(steps.roi(:), 60, 'EdgeColor', 'none'); hold on;
xline(mu, 'b-', '\mu'); xline(t, 'r-', '\mu - k s', 'LineWidth', 1.5);
%xlabel('normalised intensity'); ylabel('pixels'); title(sprintf('\\mu = %.2f, s = %.2f, threshold %.2f', mu, sd, t));
nexttile(tl); 
imshow(steps.threshold');
%title('adaptive threshold');
nexttile(tl); 
imshow(steps.grown'); 
%title('region growing');
nexttile(tl); 
imshow(mat2gray(I(rx, ry, k0)'), []); 
hold on;
visboundaries(S(rx, ry, k0)', 'Color', 'r', 'LineWidth', 0.8); 
visboundaries(mask(rx, ry)', 'Color', 'g', 'LineWidth', 0.8);
%title(sprintf('opening + filling, Dice %.2f', diceCoef(mask, S(:, :, k0))));
%%
%[text] ## 1c. Propagation: one step from k0 to k0 + 1
%[text] The accepted mask M\_k, eroded by 1 mm, becomes the marker on the next slice: mu and s are measured on the marker, so the threshold follows the tumour from slice to slice. The candidate is kept within 1 mm of M\_k and may grow at most 1.2 times. Propagation stops, in each direction, below 20 mm^2, below 15% of the largest area or at a Dice below 0.2 with M\_k.
M3 = propagateVolume(I, sp, k0, seeds, P, Q);
% the first steps of propagateVolume are repeated here only to show them; the last
% panel is the real result of propagateVolume, so a difference would stay visible.
k1 = k0 + 1; prev = M3(:, :, k0); img1 = I(:, :, k1);
marker = imerode(prev, strel('disk', round(Q.erodeMM / pxmm), 0));
if ~any(marker(:)), marker = prev; end
Pk = P; Pk.perSeed = false;
cand = segmentSlice(img1, marker, sp(1:2), Pk);
band = imdilate(prev, strel('disk', round(Q.clipMM / pxmm), 0));

f = figure('Name', '1c. One propagation step', 'Position', [50 300 1300 360]); theme(f, 'light');
tl = tiledlayout(f, 1, 4, 'TileSpacing', 'compact', 'Padding', 'compact');
nexttile(tl); imshow(mat2gray(img1(rx, ry)'), []); hold on;
visboundaries(prev(rx, ry)', 'Color', 'y', 'LineWidth', 0.8); visboundaries(marker(rx, ry)', 'Color', 'c', 'LineWidth', 0.8);
title('M_{k_0} (yellow) and marker (cyan)');
nexttile(tl); imshow(mat2gray(img1(rx, ry)'), []); hold on;
visboundaries(cand(rx, ry)', 'Color', 'm', 'LineWidth', 0.8);
title(sprintf('candidate from the marker: %d px', nnz(cand)));
nexttile(tl); imshow(mat2gray(img1(rx, ry)'), []); hold on;
visboundaries(band(rx, ry)', 'Color', 'y', 'LineStyle', '--', 'LineWidth', 0.8);
visboundaries(cand(rx, ry)' & band(rx, ry)', 'Color', 'g', 'LineWidth', 0.8);
title(sprintf('within 1 mm of M_{k_0}: %d px', nnz(cand & band)));
nexttile(tl); imshow(mat2gray(img1(rx, ry)'), []); hold on;
visboundaries(S(rx, ry, k1)', 'Color', 'r', 'LineWidth', 0.8); visboundaries(M3(rx, ry, k1)', 'Color', 'g', 'LineWidth', 0.8);
title(sprintf('accepted M_{k_0+1}, Dice %.2f', diceCoef(M3(:, :, k1), S(:, :, k1))));
%%
%[text] ## 1d. The whole volume
%[text] The 3D mask is the union of the accepted slices. The slice Dice is highest near the start slice and drops towards the ends of the tumour, where propagation stops or leaks.
zs = find(squeeze(any(S | M3, [1 2])))';
dz = arrayfun(@(k) diceCoef(M3(:, :, k), S(:, :, k)), zs);
fprintf('Volumetric Dice %.3f; tumour on %d slices, segmented %d slices (%d outside the tumour)\n', ...
    diceCoef(M3, S), nnz(any(S, [1 2])), nnz(any(M3, [1 2])), nnz(any(M3, [1 2]) & ~any(S, [1 2])));

f = figure('Name', '1d. Whole volume', 'Position', [50 300 1200 450]); theme(f, 'light');
tl = tiledlayout(f, 1, 2, 'TileSpacing', 'compact');
zt = find(squeeze(any(S, [1 2])));
nexttile(tl); xregion(min(zt) - 0.5, max(zt) + 0.5); hold on; bar(zs, dz); xline(k0, 'r--', 'k_0');
xlabel('slice'); ylabel('slice Dice'); ylim([0 1]);
title(sprintf('Volumetric Dice %.2f (shaded: slices with tumour)', diceCoef(M3, S)));
nexttile(tl); render3D(S, M3, sp);
title('3D (red: expert, green: result)');
%%
%[text] ## 2. Seeds placed by clicking, as an operator would
%[text] In the experiments the seeds come from the expert mask. Here they are placed by hand: a window opens on slice kClick; click once on each visible piece of the tumour, then press Done. The red contour is the expert mask, shown only as a reference (showExpert = false hides it). The rest of the method is unchanged.
kClick = k0;            % start slice: change it to try another one
showExpert = true;
seedsClick = clickSeeds(I(:, :, kClick), S(:, :, kClick) & showExpert);
M3click = propagateVolume(I, sp, kClick, seedsClick, P, Q);
fprintf('%d seed(s) on slice %d: volumetric Dice %.3f (seeds from the expert mask: %.3f)\n', ...
    size(seedsClick, 1), kClick, diceCoef(M3click, S), diceCoef(M3, S));
showSlices(I, S, M3click, kClick + (-4:2:4), kClick, ...
    sprintf('Clicked seeds: volumetric Dice %.2f (red: expert, green: result)', diceCoef(M3click, S)));
%%
%[text] ## 3. Effect of the parameters on the start slice
%[text] A window with two sliders segments the start slice again with another k (threshold mu - k\*s) and another opening radius. A larger k lowers the threshold and lets in more of the tissue around the tumour, a smaller k keeps only its brightest part; a larger opening cuts the bridges but also the thin parts of the wall. This is a demonstration on a development patient, not tuning: the final values (k = 1, opening 3 mm) were chosen on the development set and frozen before the test.
exploreParameters(I(:, :, k0), S(:, :, k0), seeds, sp(1:2), P);
%%
%[text] ## Local functions
function render3D(S, M, sp)
% Surfaces of the expert mask (red, transparent) and of the result (green), in mm.
    [x, y, z] = ind2sub(size(S), find(S | M));
    cx = max(min(x) - 2, 1):min(max(x) + 2, size(S, 1));
    cy = max(min(y) - 2, 1):min(max(y) + 2, size(S, 2));
    cz = max(min(z) - 2, 1):min(max(z) + 2, size(S, 3));
    patch(isosurface(permute(S(cx, cy, cz), [2 1 3]), 0.5), 'FaceColor', 'r', 'FaceAlpha', 0.25, 'EdgeColor', 'none');
    hold on;
    if any(M(:))
        patch(isosurface(permute(M(cx, cy, cz), [2 1 3]), 0.5), 'FaceColor', 'g', 'FaceAlpha', 0.8, 'EdgeColor', 'none');
    end
    daspect(1 ./ sp); view(3); axis tight off; camlight; lighting gouraud;
end

function showSlices(I, S, M, ks, k0, ttl)
% A row of slices around the tumour (red: expert, green: result), with the slice Dice.
    [x, y] = find(any(S | M, 3));
    rx = max(min(x) - 15, 1):min(max(x) + 15, size(I, 1));
    ry = max(min(y) - 15, 1):min(max(y) + 15, size(I, 2));
    ks = ks(ks >= 1 & ks <= size(I, 3));
    f = figure('Name', ttl, 'Position', [50 300 1500 360]); theme(f, 'light');
    tl = tiledlayout(f, 1, numel(ks), 'TileSpacing', 'compact', 'Padding', 'compact'); title(tl, ttl);
    for k = ks
        nexttile(tl); imshow(mat2gray(I(rx, ry, k)'), []); hold on;
        if any(S(rx, ry, k), 'all'), visboundaries(S(rx, ry, k)', 'Color', 'r', 'LineWidth', 0.8); end
        if any(M(rx, ry, k), 'all'), visboundaries(M(rx, ry, k)', 'Color', 'g', 'LineWidth', 0.8); end
        title(sprintf('slice k_0%+d, Dice %.2f', k - k0, diceCoef(M(:, :, k), S(:, :, k))));
    end
end

function seeds = clickSeeds(img, ref)
% Opens a window on the slice: each click adds a seed ([row column] of the volume), Done ends.
    fig = uifigure('Name', 'Click on each visible piece of the tumour, then press Done', 'Position', [100 80 720 780]);
    g = uigridlayout(fig, [2 1]); g.RowHeight = {'1x', 40};
    ax = uiaxes(g);
    h = imshow(mat2gray(img'), [], 'Parent', ax); hold(ax, 'on');
    if any(ref(:))
        set(visboundaries(ax, ref', 'Color', 'r', 'LineWidth', 0.6), 'HitTest', 'off', 'PickableParts', 'none');
    end
    disableDefaultInteractivity(ax);
    title(ax, 'Click on the tumour, then press Done');
    uibutton(g, 'Text', 'Done', 'ButtonPushedFcn', @(~, ~) uiresume(fig));
    fig.UserData = zeros(0, 2);
    h.ButtonDownFcn = @(~, ev) addSeed(ax, ev, size(img));
    fig.CloseRequestFcn = @(src, ~) uiresume(src);
    uiwait(fig);
    seeds = fig.UserData; delete(fig);
    assert(~isempty(seeds), 'No seed was placed.');
end

function addSeed(ax, ev, sz)
% The slice is shown transposed: x on screen = first index, y on screen = second index.
    p = min(max(round(ev.IntersectionPoint(1:2)), 1), sz);
    fig = ancestor(ax, 'figure'); fig.UserData(end + 1, :) = p;
    plot(ax, p(1), p(2), 'y+', 'MarkerSize', 14, 'LineWidth', 2, 'PickableParts', 'none');
end

function exploreParameters(img, ref, seeds, sp, P)
% Window with two sliders (k and opening radius) that segments the slice again at each change.
    fig = uifigure('Name', 'Effect of k and of the opening radius', 'Position', [100 100 1100 600]);
    g = uigridlayout(fig, [3 2]); g.RowHeight = {'1x', 45, 45}; g.ColumnWidth = {220, '1x'};
    ga = uigridlayout(g, [1 2]); ga.Layout.Row = 1; ga.Layout.Column = [1 2];
    d.ax1 = uiaxes(ga); d.ax2 = uiaxes(ga);
    d.l1 = uilabel(g); d.l1.Layout.Row = 2; d.l1.Layout.Column = 1;
    d.sk = uislider(g, 'Limits', [0.25 3], 'Value', P.k); d.sk.Layout.Row = 2; d.sk.Layout.Column = 2;
    d.l2 = uilabel(g); d.l2.Layout.Row = 3; d.l2.Layout.Column = 1;
    d.so = uislider(g, 'Limits', [0 6], 'Value', P.openMM); d.so.Layout.Row = 3; d.so.Layout.Column = 2;
    d.img = img; d.ref = ref; d.seeds = seeds; d.sp = sp; d.P = P;
    fig.UserData = d;
    d.sk.ValueChangedFcn = @(~, ~) updateExplorer(fig);
    d.so.ValueChangedFcn = @(~, ~) updateExplorer(fig);
    updateExplorer(fig);
end

function updateExplorer(fig)
% Segments the slice with the slider values (k in steps of 0.25, opening in steps of 0.5 mm).
    d = fig.UserData; Pk = d.P;
    Pk.k = round(d.sk.Value * 4) / 4; Pk.openMM = round(d.so.Value * 2) / 2;
    d.sk.Value = Pk.k; d.so.Value = Pk.openMM;
    [mask, box, steps] = segmentSlice(d.img, d.seeds, d.sp, Pk);
    rx = box(1):box(2); ry = box(3):box(4); s = d.seeds - [box(1) - 1, box(3) - 1];
    imshow(steps.threshold', 'Parent', d.ax1); hold(d.ax1, 'on');
    plot(d.ax1, s(:, 1), s(:, 2), 'y+', 'MarkerSize', 10, 'LineWidth', 1.5); hold(d.ax1, 'off');
    title(d.ax1, sprintf('threshold \\mu - %.2f s', Pk.k));
    imshow(mat2gray(d.img(rx, ry)'), [], 'Parent', d.ax2); hold(d.ax2, 'on');
    if any(d.ref(rx, ry), 'all'), visboundaries(d.ax2, d.ref(rx, ry)', 'Color', 'r', 'LineWidth', 0.8); end
    if any(mask(rx, ry), 'all'), visboundaries(d.ax2, mask(rx, ry)', 'Color', 'g', 'LineWidth', 0.8); end
    hold(d.ax2, 'off');
    title(d.ax2, sprintf('result (green) and expert (red): Dice %.2f', diceCoef(mask, d.ref)));
    d.l1.Text = sprintf('k = %.2f   (final: %g)', Pk.k, d.P.k);
    d.l2.Text = sprintf('opening = %.1f mm   (final: %g mm)', Pk.openMM, d.P.openMM);
end

